}

module.exports = { tokenize };

'use strict';

const { ExprError } = require('./errors');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/**
 * Parse a complete token sequence into an AST. Nodes retain operator columns.
 * Flat chains (sums, products, comparisons, unary signs, ** chains) are parsed
 * with loops; only parentheses and call arguments recurse.
 */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => {
    const token = tokens[position];
    if (token.type !== 'eof') position += 1;
    return token;
  };
  const is = value => current().type === 'operator' && current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  // comparison := sum (op sum)*, kept as one chained node for Python semantics.
  function comparison() {
    const first = sum();
    if (!(current().type === 'operator' && COMPARISONS.has(current().value))) return first;
    const operands = [first];
    const operators = [];
    while (current().type === 'operator' && COMPARISONS.has(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (current().type === 'operator' && PRODUCTS.has(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /**
   * unary := ('+' | '-') unary | power;  power := primary ('**' unary)?
   * Collects segments "signs primary **" left to right, then folds from the
   * right, so ** is right-associative and binds tighter than its left sign.
   */
  function unary() {
    const segments = [];
    for (;;) {
      const signs = [];
      while (is('+') || is('-')) signs.push(take());
      const base = primary();
      if (is('**')) {
        segments.push({ signs, base, operator: take() });
      } else {
        segments.push({ signs, base, operator: null });
        break;
      }
    }
    let node = null;
    for (let i = segments.length - 1; i >= 0; i -= 1) {
      const { signs, base, operator } = segments[i];
      node = operator ? binary(operator, base, node) : base;
      for (let j = signs.length - 1; j >= 0; j -= 1) {
        node = { type: 'unary', operator: signs[j], operand: node };
      }
    }
    return node;
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      if (!FUNCTIONS.has(token.value)) throw new ExprError('Unknown function', token.column);
      take();
      const args = [];
      if (!is(')')) {
        args.push(comparison());
        while (is(',')) {
          take();
          args.push(comparison());
        }
      }
      expect(')');
      if (!args.length || (token.value === 'abs' && args.length !== 1)) {
        throw new ExprError('Wrong argument count', token.column);
      }
      return { type: 'call', name: token.value, args };
    }
    if (token.type === 'operator' && token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };

