'use strict';

const { ExprError } = require('./errors');

/** Python's float divmod (CPython float_divmod); zero results are +0. */
function floorDivMod(left, right) {
  let mod = left % right;
  let div = (left - mod) / right;
  if (mod) {
    if ((right < 0) !== (mod < 0)) {
      mod += right;
      div -= 1;
    }
  } else {
    mod = 0;
  }
  let floordiv;
  if (div) {
    floordiv = Math.floor(div);
    if (div - floordiv > 0.5) floordiv += 1;
  } else {
    floordiv = 0;
  }
  return [floordiv === 0 ? 0 : floordiv, mod === 0 ? 0 : mod];
}

/** Python's float pow special cases that differ from JavaScript's **. */
function power(operator, left, right) {
  if (right === 0 || left === 1) return 1;
  if (Math.abs(left) === 1 && Math.abs(right) === Infinity) return 1;
  if (left === 0 && right < 0 && right !== -Infinity) {
    throw new ExprError('Zero raised to a negative power', operator.column);
  }
  return left ** right;
}

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**': return power(operator, left, right);
    case '//': return floorDivMod(left, right)[0];
    case '%': return floorDivMod(left, right)[1];
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
    if (node.type === 'number') {
      result = node.value;
      frames.pop();
    } else if (node.type === 'variable') {
      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
        throw new ExprError('Unknown variable', node.column);
      }
      result = variables[node.name];
      frames.pop();
    } else if (node.type === 'unary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operand, phase: 0 });
      } else {
        result = node.operator.value === '-' ? -Number(result) : Number(result);
        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operands[0], phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.index = 0;
        frame.phase = 2;
        frames.push({ node: node.operands[1], phase: 0 });
      } else {
        const right = result;
        if (!apply(node.operators[frame.index], frame.left, right)) {
          result = false;
          frames.pop();
        } else if (frame.index + 1 === node.operators.length) {
          result = true;
          frames.pop();
        } else {
          frame.left = right;
          frame.index += 1;
          frames.push({ node: node.operands[frame.index + 1], phase: 0 });
        }
      }
    } else if (node.type === 'call') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frame.index = 0;
        frames.push({ node: node.args[0], phase: 0 });
      } else {
        const value = Number(result);
        if (frame.index === 0) frame.value = value;
        else if (node.name === 'min') frame.value = Math.min(frame.value, value);
