          result = node.name === 'abs' ? Math.abs(frame.value) : frame.value;
          frames.pop();
        } else {
          frames.push({ node: node.args[frame.index], phase: 0 });
        }
      }
    } else {
      throw new Error('Invalid AST node');
    }
  }
  return result;
}

